import {FAMILY_INTERESTS,FAMILY_SUPPORTS,PARTICIPATION,OFFLINE_ACTIVITIES,SUGGESTED_AGES} from './family-data.js';
import {familyWeeklySummary,recommendedActivities,dailyTrail,gardenFor,offlineForProfile} from './family-model.js';
import {activityById} from './teaching.js';

const familyEscape=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const familyDate=value=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(value));
export function familyHomeHTML(state,p,{icon,activityCard}){
 const summary=familyWeeklySummary(state,p.id),trail=dailyTrail(state,p.id),garden=gardenFor(state,p.id);
 const recommendations=recommendedActivities(state,p.id),inTrail=new Set(trail.steps.map(s=>s.activity.id));
 const themeIds=new Set(trail.theme.activities),themed=recommendations.filter(a=>themeIds.has(a.id)&&!inTrail.has(a.id));
 const more=(themed.length?themed:recommendations.filter(a=>!inTrail.has(a.id))).slice(0,4);
 const step=(st,i)=>{const a=st.activity,art=a.storyArt?`<img src="${familyEscape(a.storyArt)}" alt="">`:icon(a.icon||'star');
  const action=st.kind==='offline'?`data-action="offline-activity" data-id="${familyEscape(a.id)}"`:`data-action="play" data-id="${familyEscape(a.id)}"`;
  return `<li class="trail-step ${st.done?'is-done':''} kind-${st.kind}"><button ${action} aria-label="${i+1}. ${familyEscape(st.label)}: ${familyEscape(a.name)}${st.done?', feito hoje':''}"><span class="trail-art ${a.color||'peach'}" aria-hidden="true">${art}</span><span class="trail-copy"><small>${st.label}</small><strong>${familyEscape(a.name)}</strong></span><span class="trail-status" aria-hidden="true">${st.done?icon('check'):icon('arrow')}</span></button></li>`;};
 return `<section class="family-welcome"><div><h1>Pequenos momentos.<br>Grandes descobertas.</h1><p>Um convite para brincar e acompanhar as experiências de <strong>${familyEscape(p.name)}</strong>.</p></div><button class="family-child-chip" data-action="edit-family-profile">${icon('users')}<span>${p.age?p.age+' anos, ajustar perfil':'Preparar o perfil'}</span>${icon('chevron')}</button></section>${!p.age?`<section class="setup-callout"><img src="assets/lumi.svg" alt=""><div><strong>Como podemos brincar melhor?</strong><p>Informe a faixa etária, os interesses e os apoios que facilitam a participação.</p></div><button class="primary" data-action="edit-family-profile">Preparar perfil${icon('arrow')}</button></section>`:''}
<section class="trail-card ${trail.complete?'is-complete':''}" aria-labelledby="trail-title"><div class="trail-head"><div><h2 id="trail-title">Trilha de hoje</h2><p>${trail.complete?'Trilha completa! Uma estrela brilhou no jardim da Lumi.':'Três paradas curtas para fazer juntos, na ordem que quiserem.'}</p></div><span class="trail-count" aria-label="${trail.done} de ${trail.steps.length} paradas feitas">${trail.done}/${trail.steps.length}</span></div>${trail.steps.length?`<ol class="trail-steps">${trail.steps.map(step).join('')}</ol>`:'<p class="text-muted">A seleção atual não tem atividades para esta faixa. Um adulto pode ajustar em Perfil.</p>'}<button class="quiet trail-listen" data-action="family-welcome">${icon('sound')}Ouvir a Lumi</button></section>
<section class="garden-card"><button class="garden-preview" data-action="nav" data-view="garden" aria-label="Ver o jardim da Lumi: ${garden.total} plantas e ${garden.stars} estrelas">${gardenSVG(garden,{compact:true})}</button><div class="garden-copy"><h2>Jardim da Lumi</h2><p>${garden.total?`${garden.total} ${garden.total===1?'planta':'plantas'} e ${garden.stars} ${garden.stars===1?'estrela':'estrelas'}. Cada brincadeira faz nascer uma planta nova.`:'Cada brincadeira concluída faz nascer uma planta. Que tal plantar a primeira hoje?'}</p><button class="secondary" data-action="nav" data-view="garden">${icon('sprout')}Ver o jardim</button></div></section>
<section class="theme-section"><div class="section-heading"><div><h2>Tema do mês: ${familyEscape(trail.theme.name)}</h2><p>${familyEscape(trail.theme.description)}</p></div><button class="quiet" data-action="nav" data-view="library">Ver todas${icon('arrow')}</button></div><div class="family-suggestions">${more.length?more.map(a=>activityCard(a,true)).join(''):'<div class="empty-state"><p>Um adulto pode ativar mais atividades em Perfil.</p></div>'}</div></section>
<div class="family-quick-summary"><div><span class="icon-circle">${icon('sprout')}</span><div><strong>${summary.total} experiências nos últimos 7 dias</strong><p>${summary.sessions.length} na Lumi e ${summary.offline.length} fora da tela, informadas pela família</p></div></div><button class="quiet" data-action="nav" data-view="family">Ver descobertas${icon('arrow')}</button></div><p class="family-footnote">${icon('heart')}A criança pode participar falando, apontando, usando seu recurso de comunicação ou com apoio de um adulto.</p>`;
}
// ——— Jardim ———
const PLANT_ART={
 flor:'<path d="M20 58V30" stroke="#5E9A5C" stroke-width="3"/><path d="M20 44q-9-2-10-9 8-1 10 9" fill="#7DB36F"/>'+[0,72,144,216,288].map(r=>`<ellipse cx="20" cy="18" rx="5" ry="8" fill="#F29AB2" transform="rotate(${r} 20 26)"/>`).join('')+'<circle cx="20" cy="26" r="4.5" fill="#F7C548"/>',
 girassol:'<path d="M20 58V28" stroke="#5E9A5C" stroke-width="3"/><path d="M20 46q9-2 10-9-8-1-10 9" fill="#7DB36F"/>'+[0,45,90,135,180,225,270,315].map(r=>`<ellipse cx="20" cy="13" rx="3.6" ry="7" fill="#F5C443" transform="rotate(${r} 20 22)"/>`).join('')+'<circle cx="20" cy="22" r="5.5" fill="#8A5A2B"/>',
 tulipa:'<path d="M20 58V30" stroke="#5E9A5C" stroke-width="3"/><path d="M20 50q-10-4-9-14 7 3 9 14" fill="#7DB36F"/><path d="M11 18q2 14 9 14t9-14l-5 5-4-8-4 8Z" fill="#E86A5A"/>',
 trevo:'<path d="M20 58V34" stroke="#4E8B4B" stroke-width="3"/><circle cx="14" cy="28" r="7" fill="#6FAE61"/><circle cx="26" cy="28" r="7" fill="#6FAE61"/><circle cx="20" cy="19" r="7" fill="#7DBB6E"/>',
 cogumelo:'<rect x="16" y="36" width="8" height="22" rx="3" fill="#F6EAD3"/><path d="M6 38q2-18 14-18t14 18Z" fill="#E0614E"/><circle cx="14" cy="30" r="2.5" fill="#fff"/><circle cx="24" cy="27" r="3" fill="#fff"/><circle cx="27" cy="34" r="2" fill="#fff"/>',
 morango:'<path d="M20 58V40" stroke="#5E9A5C" stroke-width="3"/><path d="M11 26q9 30 18 0Z" fill="#E4505A"/><path d="M11 26l4-5 5 4 5-4 4 5Z" fill="#5E9A5C"/><circle cx="16" cy="32" r="1.2" fill="#FBE3A0"/><circle cx="23" cy="34" r="1.2" fill="#FBE3A0"/><circle cx="20" cy="40" r="1.2" fill="#FBE3A0"/>',
 arbusto:'<circle cx="12" cy="44" r="9" fill="#5F9E58"/><circle cx="28" cy="44" r="9" fill="#5F9E58"/><circle cx="20" cy="36" r="11" fill="#72B067"/><circle cx="16" cy="36" r="1.8" fill="#F29AB2"/><circle cx="25" cy="42" r="1.8" fill="#F29AB2"/>',
 coracao:'<path d="M20 58V32" stroke="#5E9A5C" stroke-width="3"/><path d="M20 34q-14-10-8-18 5-5 8 2 3-7 8-2 6 8-8 18Z" fill="#EC7A95"/>'
};
function rnd(i){const x=Math.sin(i*12.9898)*43758.5453;return x-Math.floor(x);}
export function gardenSVG(garden,{compact=false}={}){
 const plants=garden.plants.slice(compact?-14:-48),per=compact?14:8,rows=Math.max(1,Math.ceil(plants.length/per));
 const w=compact?320:400,ground=compact?88:150,h=compact?140:ground+rows*52+40,stars=Math.min(garden.stars,compact?6:30);
 const plantSVG=plants.map((pl,i)=>{const row=Math.floor(i/per),col=i%per,scale=compact?.72:1.25;const x=(compact?14:22)+col*((w-(compact?40:60))/(per-1||1))+rnd(i)*8-4,y=ground-4+row*52+rnd(i+7)*6;
  return `<g transform="translate(${x.toFixed(1)} ${(y-58*scale).toFixed(1)}) scale(${scale.toFixed(2)})" class="garden-plant ${i===plants.length-1&&garden.today?'is-new':''}">${PLANT_ART[pl.plant]||PLANT_ART.flor}</g>`;}).reverse().join('');
 const starSVG=Array.from({length:stars},(_,i)=>`<path transform="translate(${(30+rnd(i+50)*(w-60)).toFixed(0)} ${(14+rnd(i+90)*(ground-90)).toFixed(0)}) scale(${compact?.6:.9})" d="m10 0 3 6.5 7 1-5 5 1.2 7L10 16l-6.2 3.5L5 12.5 0 7.5l7-1Z" fill="#F5C443"/>`).join('');
 const empty=!plants.length?`<g transform="translate(${w/2-20} ${ground-46}) scale(${compact?.8:1.2})"><path d="M20 40V26" stroke="#7a6a4f" stroke-width="3" stroke-dasharray="3 3"/><ellipse cx="20" cy="42" rx="12" ry="4" fill="#9c7550"/></g>`:'';
 return `<svg class="garden-svg ${compact?'is-compact':''}" viewBox="0 0 ${w} ${h}" role="img" aria-label="Jardim com ${garden.total} plantas e ${garden.stars} estrelas"><rect width="${w}" height="${h}" rx="${compact?18:28}" fill="#E4F0EA"/><circle cx="${w-(compact?50:44)}" cy="38" r="${compact?16:22}" fill="#F7D98A"/>${starSVG}<path d="M0 ${ground}q${w*.25} -24 ${w*.5} -6t${w*.5} 4V${h}H0Z" fill="#CFE3BF"/><path d="M0 ${ground+ (compact?18:30)}q${w*.3} -16 ${w*.6} -4t${w*.4} 2V${h}H0Z" fill="#BCD7A8"/>${plantSVG}${empty}${compact?`<image href="assets/lumi.svg" x="8" y="${ground-58}" width="44" height="50"/>`:''}</svg>`;
}
export function familyGardenHTML(state,p,icon){
 const garden=gardenFor(state,p.id),trail=dailyTrail(state,p.id);
 const legend=[['flor','Histórias'],['girassol','Conversa'],['tulipa','Sons'],['cogumelo','Cores, formas e observação'],['morango','Quantidades e tamanhos'],['arbusto','Corpo e movimento'],['coracao','Sentimentos'],['trevo','Letras e palavras']];
 return `<div class="page-heading"><div><h1>O jardim de ${familyEscape(p.name)}.</h1><p>Cada brincadeira concluída faz nascer uma planta. Cada dia com a trilha completa acende uma estrela. Não há pontos nem comparação: é só um jeito de lembrar o que vocês viveram juntos.</p></div></div>
<section class="garden-stage">${gardenSVG(garden)}</section>
<div class="garden-stats"><article><strong>${garden.total}</strong><span>${garden.total===1?'planta':'plantas'}</span></article><article><strong>${garden.stars}</strong><span>${garden.stars===1?'estrela':'estrelas'}</span></article><article><strong>${trail.done}/${trail.steps.length}</strong><span>trilha de hoje</span></article></div>
<section class="panel"><h3>O que cada planta conta</h3><ul class="garden-legend">${legend.map(([k,label])=>`<li><svg viewBox="0 0 40 60" aria-hidden="true">${PLANT_ART[k]}</svg>${label}</li>`).join('')}</ul></section>`;
}
export function familyDiscoveriesHTML(state,p,icon,{voices=false}={}){
 const s=familyWeeklySummary(state,p.id),labels=Object.fromEntries(PARTICIPATION);
 const history=[...s.sessions.map(session=>({kind:'digital',date:session.createdAt,name:session.activityName||activityById(state,session.activityId,{includeDrafts:true})?.name||'Atividade',session})),...s.offline.map(o=>({kind:'offline',date:o.createdAt,name:OFFLINE_ACTIVITIES.find(a=>a.id===o.activityId)?.name||'Brincadeira fora da tela',observation:o}))].sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)).slice(0,10);
 return `<div class="page-heading family-page-heading"><div><div class="eyebrow">UM OLHAR CARINHOSO SOBRE AS EXPERIÊNCIAS</div><h1>As descobertas de ${familyEscape(p.name)}.</h1><p>Últimos 7 dias · ${familyDate(s.from)} a ${familyDate(s.until)}</p></div><div class="button-row"><button class="primary" data-action="share-summary">${icon('share')}Enviar resumo</button><button class="secondary" data-action="export-family-summary">${icon('download')}Baixar resumo</button><button class="secondary" data-action="print-family-summary">${icon('print')}Imprimir</button></div></div><div class="family-summary-grid"><article class="family-metric"><span>${icon('compass')}Na Lumi</span><strong>${s.sessions.length}</strong><p>Brincadeiras concluídas</p></article><article class="family-metric"><span>${icon('hand')}Fora da tela</span><strong>${s.offline.length}</strong><p>Experiências informadas pela família</p></article><article class="family-metric"><span>${icon('heart')}Seu olhar</span><strong>${s.observations.length}</strong><p>Observações do responsável</p></article></div>${!s.hasData?`<section class="family-empty panel"><img src="assets/lumi.svg" alt=""><h2>A primeira descoberta começa aqui.</h2><p>Depois de uma brincadeira, este espaço mostrará o que foi registrado. Você também pode contar como foi uma experiência fora da tela.</p><button class="primary" data-action="nav" data-view="library">Escolher uma brincadeira${icon('arrow')}</button></section>`:`<section class="panel family-reading"><div class="eyebrow">O QUE ESTES REGISTROS CONTAM</div><h2>Um retrato das brincadeiras.</h2><p><span class="source-label">Registrado na Lumi</span>${familyEscape(s.firstTryText)}</p><p><span class="source-label family-source">Informado pelo responsável</span>${familyEscape(s.supportText)}</p><div class="metric-note">A primeira tentativa não informa se houve ajuda. Estes registros descrevem as atividades e os relatos da família; não representam uma avaliação do desenvolvimento global ou comparação com outras crianças.</div></section>`}<section class="panel"><div class="panel-heading"><div><h3>Por onde passaram as descobertas?</h3><p>Participação nas experiências, sem notas ou níveis.</p></div>${icon('sprout')}</div><div class="family-areas">${s.areas.map(a=>`<article><span class="icon-circle">${icon(a.icon)}</span><div><strong>${a.label}</strong><p>${a.digital+a.offline?`${a.digital} na Lumi · ${a.offline} fora da tela`:'Ainda sem experiências registradas no período'}</p></div></article>`).join('')}</div></section><section class="panel family-timeline"><div class="panel-heading"><h3>Momentos para lembrar</h3><span class="text-muted">Até dez registros recentes</span></div>${history.length?history.map(item=>{const o=item.observation||(state.observations||[]).find(o=>o.sessionId===item.session.id);return `<article class="family-timeline-row"><span class="icon-circle">${icon(item.kind==='offline'?'hand':'book')}</span><div><strong>${familyEscape(item.name)}</strong><small>${familyDate(item.date)} · ${item.kind==='offline'?'Brincadeira fora da tela':'Brincadeira na Lumi'}</small><p>${o?familyEscape(labels[o.participation]):'Participação ainda não informada pelo responsável.'}</p>${o?.note?`<p class="family-note">${familyEscape(o.note)}</p>`:''}</div>${item.session?`<button class="quiet" data-action="observe-session" data-session="${familyEscape(item.session.id)}">${o?'Editar observação':'Contar como foi'}${icon('arrow')}</button>`:''}</article>`;}).join(''):'<p class="text-muted">Os momentos registrados aparecerão aqui.</p>'}</section>${voices?`<section class="panel voices-panel" id="voices-panel"><div class="panel-heading"><div><h3>Recontos gravados</h3><p>A voz da criança contando as histórias. Fica só neste aparelho.</p></div>${icon('mic')}</div><ul class="voices-list" id="voices-list"><li class="text-muted">Carregando…</li></ul></section>`:''}`;
}
export function familyProfileHTML(state,p,icon){
 const enabled=FAMILY_SUPPORTS.filter(([key])=>p.supports?.[key]);
 return `<div class="page-heading"><div><div class="eyebrow">CADA FAMÍLIA TEM SEU JEITO</div><h1>Um perfil, muitas possibilidades.</h1><p>Faixa etária, interesses e apoios podem ser ajustados a qualquer momento.</p></div></div><section class="panel family-profile-card"><img src="assets/lumi.svg" alt=""><div><h2>${familyEscape(p.name)}</h2><p>${p.age?p.age+' anos':'Faixa etária ainda não informada'}${p.attendsSchool===true?' · Já frequenta a escola':p.attendsSchool===false?' · Ainda não frequenta a escola':''}</p><div class="family-chips">${p.interests.map(i=>`<span>${familyEscape(i)}</span>`).join('')}</div></div><button class="primary" data-action="edit-family-profile">Ajustar perfil${icon('arrow')}</button></section><section class="panel"><div class="panel-heading"><div><h3>O que facilita a participação?</h3><p>Você escolhe os apoios, sem precisar informar um diagnóstico.</p></div>${icon('heart')}</div>${enabled.length?`<div class="family-chips">${enabled.map(([,label])=>`<span>${label}</span>`).join('')}</div>`:'<p class="text-muted">Nenhum ajuste adicional foi selecionado.</p>'}<p class="family-profile-note">Idade e preferências orientam as sugestões. As adaptações de acesso não equivalem a uma intervenção ou a exercícios clínicos específicos.</p><button class="quiet" data-action="edit-family-profile">Ajustar apoios${icon('arrow')}</button></section><section class="panel family-profile-tools"><h3>Mais de um explorador por aqui?</h3><p>O histórico fica separado para cada perfil.</p><div class="button-row"><button class="secondary" data-action="profiles">${icon('users')}Trocar perfil</button><button class="secondary" data-action="new-family-profile">${icon('plus')}Adicionar perfil</button></div></section><section class="panel family-profile-tools"><h3>Preferências da experiência</h3><div class="button-row"><button class="secondary" data-action="settings">${icon('settings')}Som, texto e pausas</button><button class="secondary" data-action="backup-family">${icon('download')}Guardar uma cópia dos registros</button><button class="secondary" data-action="restore-family">${icon('plus')}Restaurar uma cópia</button><input type="file" id="family-backup-file" accept=".json,application/json" hidden></div><p class="family-profile-note">Prévia de testes: os perfis e os registros ficam neste navegador. Para levar os registros a outro aparelho, exporte uma cópia. Não há contas ou sincronização automática nesta etapa.</p></section><section class="family-content-tools"><button class="quiet" data-action="nav" data-view="school">${icon('book')}Conteúdo da prévia · área de revisão</button><button class="quiet" data-action="teacher-review">Enviar meu olhar sobre a prévia${icon('arrow')}</button></section>`;
}
export function familyProfileFormHTML(profile,icon){
 const p=profile||{name:'',age:null,avatar:'fox',interests:[],supports:{}};
 return `<p class="modal-description">Use um apelido para este teste. A Lumi começa com experiências para crianças de 3 a 5 anos.</p><form id="family-profile-form"><div class="editor-two-columns"><div class="form-field"><label for="family-name">Como vamos chamar a criança?</label><input id="family-name" maxlength="30" minlength="2" value="${familyEscape(p.name)}" placeholder="Apelido" required></div><div class="form-field"><label for="family-age">Faixa etária</label><select id="family-age" required><option value="">Escolha...</option>${[3,4,5].map(age=>`<option value="${age}" ${p.age===age?'selected':''}>${age} anos</option>`).join('')}</select></div></div><div class="editor-two-columns"><div class="form-field"><label for="family-school">Já frequenta a escola?</label><select id="family-school"><option value="">Prefiro não informar</option><option value="yes" ${p.attendsSchool===true?'selected':''}>Sim</option><option value="no" ${p.attendsSchool===false?'selected':''}>Ainda não</option></select></div><div class="form-field"><label for="family-avatar">Companheiro de aventura</label><select id="family-avatar">${[['fox','Raposa'],['cat','Gato'],['frog','Sapo'],['owl','Coruja']].map(([value,label])=>`<option value="${value}" ${p.avatar===value?'selected':''}>${label}</option>`).join('')}</select></div></div><fieldset class="family-fieldset"><legend>O que chama a atenção por aí?</legend><div class="family-checkbox-chips">${FAMILY_INTERESTS.map(i=>`<label><input name="family-interest" type="checkbox" value="${i}" ${p.interests.includes(i)?'checked':''}>${i}</label>`).join('')}</div></fieldset><fieldset class="family-fieldset"><legend>Apoios para brincar com conforto</legend>${FAMILY_SUPPORTS.map(([key,label,description])=>`<label class="support-option"><input type="checkbox" name="family-support" value="${key}" ${p.supports?.[key]?'checked':''}><span><strong>${label}</strong><small>${description}</small></span></label>`).join('')}</fieldset><div id="family-form-error" class="form-error" role="alert"></div><button class="primary full" type="submit">Salvar perfil${icon('check')}</button></form>`;
}
